    fp=ensure_file_arg(fp)
    now=get_now()
    stop_dt=now
    if tstr is not None:
        parsed,err=parse_time_arg(tstr)
        if parsed is None:
            if err=="out_of_range":
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input is out of range)\n')
            else:
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input contains invalid characters)\n')
        else:
            stop_dt=parsed
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    any_stop=False
    for act in acts:
        if act["end"] is None:
            diff=stop_dt-act["start"]
            mins=int(diff.total_seconds()//60)
            if mins<0: mins=0
            dur=format_duration(mins)
            oprint(f'Stopped activity: "{act["description"]}" ({act["project"]}) started at {format_datetime(act["start"])} ({dur})\n')
            act["end"]=stop_dt
            any_stop=True
    if any_stop:
        write_file(fp, acts)

def handle_cancel(fp, args):
    if "-h" in args or "--help" in args:
        oprint(HELP_CANCEL)
        sys.exit(0)
    if args:
        for a in args:
            if a.startswith("-"):
                error_sub_usage("cancel", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
            else:
                error_sub_usage("cancel", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    running=[a for a in acts if a["end"] is None]
    for act in running:
        oprint(f'Canceled activity: "{act["description"]}" ({act["project"]}) started at {format_datetime(act["start"])}\n')
    remaining=[a for a in acts if a["end"] is not None]
    write_file(fp, remaining)

def handle_change(fp, args):
    if "-h" in args or "--help" in args:
        oprint(HELP_CHANGE)
        sys.exit(0)
    desc=None; proj=None; tstr=None
    i=0
    while i<len(args):
        a=args[i]
        if a in ("-d","--description"):
            if i+1>=len(args):
                error_sub_usage("change", f"error: The argument '{a} <DESCRIPTION>' requires a value but none was supplied")
            desc=args[i+1]; i+=2
        elif a in ("-p","--project"):
            if i+1>=len(args):
                error_sub_usage("change", f"error: The argument '{a} <PROJECT>' requires a value but none was supplied")
            proj=args[i+1]; i+=2
        elif a in ("-t","--time"):
            if i+1>=len(args):
                error_sub_usage("change", f"error: The argument '{a} <TIME>' requires a value but none was supplied")
            tstr=args[i+1]; i+=2
        elif a.startswith("-"):
            error_sub_usage("change", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        else:
            error_sub_usage("change", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    running=[a for a in acts if a["end"] is None]
    if not running:
        return
    new_start=None
    if tstr is not None:
        parsed,err=parse_time_arg(tstr)
        if parsed is None:
            if err=="out_of_range":
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input is out of range)\n')
            else:
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input contains invalid characters)\n')
        else:
            new_start=parsed
    if desc is None and proj is None and new_start is None:
        return
    for act in running:
        if desc is not None:
            act["description"]=desc
        if proj is not None:
            act["project"]=proj
        if new_start is not None:
            act["start"]=new_start
        oprint(f'Changed activity: "{act["description"]}" ({act["project"]}) started at {format_datetime(act["start"])}\n')
    write_file(fp, acts)

def handle_continue(fp, args):
    if "-h" in args or "--help" in args:
        oprint(HELP_CONTINUE)
        sys.exit(0)
    desc=None; proj=None; tstr=None
    positional=[]
    i=0
    while i<len(args):
        a=args[i]
        if a in ("-d","--description"):
            if i+1>=len(args):
                error_sub_usage("continue", f"error: The argument '{a} <DESCRIPTION>' requires a value but none was supplied")
            desc=args[i+1]; i+=2
        elif a in ("-p","--project"):
            if i+1>=len(args):
                error_sub_usage("continue", f"error: The argument '{a} <PROJECT>' requires a value but none was supplied")
            proj=args[i+1]; i+=2
        elif a in ("-t","--time"):
            if i+1>=len(args):
                error_sub_usage("continue", f"error: The argument '{a} <TIME>' requires a value but none was supplied")
            tstr=args[i+1]; i+=2
