            positional.append(a); i+=1
    if len(positional)>1:
        error_sub_usage("continue", f"error: Found argument '{positional[1]}' which wasn't expected, or isn't valid in this context")
    number=0
    if positional:
        try:
            number=int(positional[0])
        except:
            oprint(f'Can not parse "{positional[0]}" as number. Argument for -n/--number is ignored\n')
            number=0
    fp=ensure_file_arg(fp)
