def format_duration(mins):
    if mins <1:
        return "<1m"
    h=mins//60
    m=mins%60
    if h==0:
        return f"{m:02d}m"
    else:
        return f"{h}h {m:02d}m"

def parse_datetime_str(s):
    try:
        return dt.strptime(s, "%Y-%m-%d %H:%M")
    except:
        return None

def parse_date_str(s):
    try:
        return dt.strptime(s, "%Y-%m-%d").date()
    except:
        return None

def parse_time_arg(s):
    if not re.match(r'^\d{1,2}:\d{2}$', s):
        return None, "invalid_chars"
    try:
        h,m=map(int,s.split(":"))
    except:
        return None, "invalid_chars"
    if h<0 or h>23 or m<0 or m>59:
        return None, "out_of_range"
    today=ddate.today()
    return dt.combine(today, dtime(h,m)), None

def parse_duration_str(s):
    if not s: return None
    suffix=s[-1]
    if suffix not in ('m','h'):
        return None
    num=s[:-1]
    if not num.isdigit():
        return None
    try:
        n=int(num)
    except:
        return None
    # Note: original treats "0m" as valid but later round_minutes==0 leads to weird 1970 epoch? We keep as is.
    if suffix=='m':
        return n
    else:
        return n*60

def round_datetime(d, round_minutes):
    if not round_minutes:
        return d
    # round to nearest multiple of round_minutes
    # use half up
    mins=d.hour*60 + d.minute
    rounded=int(mins/round_minutes + 0.5)*round_minutes
    days_add=rounded//1440
    rm=rounded%1440
    nh=rm//60
    nm=rm%60
    new_date=d.date()+timedelta(days=days_add)
    return dt.combine(new_date, dtime(nh,nm))

def escape_text(s):
    return s.replace("\\", "\\\\").replace("|", "\\|")

def deescape_and_split(line):
    # split on unescaped |
    segs=[]
    cur=[]
    i=0
    n=len(line)
    while i<n:
        c=line[i]
        if c=="\\":
            if i+1<n:
                nxt=line[i+1]
                if nxt=="\\" or nxt=="|":
                    cur.append(nxt)
                    i+=2
                else:
