def get_now():
    return dt.now().replace(second=0, microsecond=0)

def format_datetime(d):
    return d.strftime("%Y-%m-%d %H:%M")

def format_time(d):
    return d.strftime("%H:%M")

def format_duration(mins):
    if mins < 1:
        return "<1m"
    h=mins//60
    m=mins%60
    if h==0:
        return f"{m:02d}m"
    else:
        return f"{h}h {m:02d}m"

def parse_datetime_str(s):
    try:
        return dt.strptime(s, "%Y-%m-%d %H:%M")
    except:
        return None

def parse_date_str(s):
    try:
        return dt.strptime(s, "%Y-%m-%d").date()
    except:
        return None

def parse_time_arg(s):
    if not re.match(r'^\d{1,2}:\d{2}$', s):
        return None, "invalid_chars"
    try:
        h,m=map(int, s.split(":"))
    except:
        return None, "invalid_chars"
    if h<0 or h>23 or m<0 or m>59:
        return None, "out_of_range"
    today=ddate.today()
    return dt.combine(today, dtime(h,m)), None

def parse_duration_str(s):
    if not s:
        return None
    suffix=s[-1]
    if suffix not in ('m','h'):
        return None
    num=s[:-1]
    if not num.isdigit():
        return None
    try:
        n=int(num)
    except:
        return None
    if suffix=='m':
        return n
    else:
        return n*60

def round_datetime(d, rnd):
    if not rnd:
        return d
    mins=d.hour*60 + d.minute
    rounded=int(mins/rnd + 0.5)*rnd
    days_add=rounded//1440
    rm=rounded%1440
    nh=rm//60
    nm=rm%60
    new_date=d.date()+timedelta(days=days_add)
    return dt.combine(new_date, dtime(nh,nm))

def escape_text(s):
    return s.replace("\\", "\\\\").replace("|", "\\|")

def deescape_and_split(line):
    segs=[]
    cur=[]
    i=0
    n=len(line)
    while i<n:
        c=line[i]
        if c=="\\":
            if i+1<n:
                nxt=line[i+1]
                if nxt=="\\" or nxt=="|":
                    cur.append(nxt)
                    i+=2
                else:
                    cur.append(nxt)
                    i+=2
            else:
                i+=1
        elif c=="|":
            segs.append(''.join(cur).strip())
            cur=[]
            i+=1
        else:
            cur.append(c)
            i+=1
    segs.append(''.join(cur).strip())
    return segs

def read_file(path):
    if not os.path.exists(path):
        return None, None, "not_found"
    try:
        with open(path,'r',encoding='utf-8',errors='replace') as f:
            lines=f.readlines()
    except Exception as e:
        return None,None,str(e)
    acts=[]
    errs=[]
    for idx, raw in enumerate(lines, start=1):
        line=raw.rstrip("\n")
        if line.strip()=="":
            errs.append((idx, line, "activity"))
            continue
        segs=deescape_and_split(line)
        if len(segs)<2:
            errs.append((idx, line, "activity"))
            continue
        date_part=segs[0]
        project=segs[1] if len(segs)>=2 else ""
        description=segs[2] if len(segs)>=3 else ""
        if " - " in date_part:
            parts=date_part.split(" - ",1)
            s_str=parts[0].strip()
            e_str=parts[1].strip()
            sd=parse_datetime_str(s_str)
            ed=parse_datetime_str(e_str)
            if sd is None or ed is None:
                errs.append((idx, line, "date"))
                continue
            acts.append({"start":sd,"end":ed,"project":project,"description":description,"line_no":idx,"raw":line})
        else:
            sd=parse_datetime_str(date_part.strip())
            if sd is None:
                errs.append((idx, line, "date"))
                continue
            acts.append({"start":sd,"end":None,"project":project,"description":description,"line_no":idx,"raw":line})
    return acts, errs, None

def write_file(path, acts):
    acts_sorted=sorted(acts, key=lambda a: a["start"])
    try:
        with open(path,'w',encoding='utf-8') as f:
            for a in acts_sorted:
                start_s=format_datetime(a["start"])
                proj_esc=escape_text(a["project"])
                desc_esc=escape_text(a["description"])
                if a["end"] is not None:
                    end_s=format_datetime(a["end"])
                    f.write(f"{start_s} - {end_s} | {proj_esc} | {desc_esc}\n")
                else:
                    f.write(f"{start_s} | {proj_esc} | {desc_esc}\n")
    except Exception as e:
        eprint(f"Error: Could not write to file: {path}\n\nCaused by:\n    {e}\n")
        sys.exit(1)

def ensure_file_arg(fp):
    if fp is None:
        eprint("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable\n")
        sys.exit(1)
    return fp

def error_sub_usage(sub, msg):
    usage_map={
        "cancel":"    executable cancel",
        "change":"    executable change [OPTIONS]",
        "check":"    executable check",
        "continue":"    executable continue [OPTIONS] [NUMBER]",
        "current":"    executable current",
        "edit":"    executable edit [OPTIONS]",
        "last":"    executable last [OPTIONS]",
        "list":"    executable list [FLAGS] [OPTIONS]",
        "projects":"    executable projects [FLAGS]",
        "report":"    executable report [FLAGS] [OPTIONS]",
        "sanity":"    executable sanity",
        "search":"    executable search <SEARCH_TERM>",
        "start":"    executable start [OPTIONS] --description <DESCRIPTION> --project <PROJECT>",
        "status":"    executable status [OPTIONS]",
        "stop":"    executable stop [OPTIONS]",
    }
    usage=usage_map.get(sub, f"    executable {sub}")
    eprint(f"{msg}\n\nUSAGE:\n{usage}\n\nFor more information try --help\n")
    sys.exit(1)

def handle_start(fp, args):
    if "-h" in args or "--help" in args:
        oprint(HELP_START)
        sys.exit(0)
    desc=None; proj=None; tstr=None
    i=0
    while i<len(args):
        a=args[i]
        if a in ("-d","--description"):
            if i+1>=len(args):
                error_sub_usage("start", f"error: The argument '{a} <DESCRIPTION>' requires a value but none was supplied")
            desc=args[i+1]; i+=2
        elif a in ("-p","--project"):
            if i+1>=len(args):
                error_sub_usage("start", f"error: The argument '{a} <PROJECT>' requires a value but none was supplied")
            proj=args[i+1]; i+=2
        elif a in ("-t","--time"):
            if i+1>=len(args):
                error_sub_usage("start", f"error: The argument '{a} <TIME>' requires a value but none was supplied")
            tstr=args[i+1]; i+=2
        elif a.startswith("-"):
            error_sub_usage("start", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        else:
            error_sub_usage("start", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
    if desc is None:
        eprint("error: The following required arguments were not provided:\n    --description <DESCRIPTION>\n\nUSAGE:\n    executable start [OPTIONS] --description <DESCRIPTION> --project <PROJECT>\n\nFor more information try --help\n")
        sys.exit(1)
    if proj is None:
        eprint("error: The following required arguments were not provided:\n    --project <PROJECT>\n\nUSAGE:\n    executable start [OPTIONS] --description <DESCRIPTION> --project <PROJECT>\n\nFor more information try --help\n")
        sys.exit(1)
    fp=ensure_file_arg(fp)
    now=get_now()
    start_dt=now
    if tstr is not None:
        parsed,err=parse_time_arg(tstr)
        if parsed is None:
            if err=="out_of_range":
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input is out of range)\n')
            else:
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input contains invalid characters)\n')
        else:
            start_dt=parsed
    acts=[]
    if os.path.exists(fp):
        a,e,err=read_file(fp)
        if err=="not_found":
            a=[]
        elif err:
            eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
            sys.exit(1)
        else:
            acts=a
    else:
        acts=[]
    for act in acts:
        if act["end"] is None:
            diff=start_dt-act["start"]
            mins=int(diff.total_seconds()//60)
            if mins<0: mins=0
            dur=format_duration(mins)
            oprint(f'Stopped activity: "{act["description"]}" ({act["project"]}) started at {format_datetime(act["start"])} ({dur})\n')
            act["end"]=start_dt
    acts.append({"start":start_dt,"end":None,"project":proj,"description":desc,"line_no":0,"raw":""})
    oprint(f'Started activity: "{desc}" ({proj}) at {format_datetime(start_dt)}\n')
    write_file(fp, acts)

