                error_sub_usage("list", f"error: The argument '{a} <PROJECT>' requires a value but none was supplied")
            project_filter=args[i+1]; i+=2
        elif a=="--round":
            if i+1>=len(args):
                error_sub_usage("list", f"error: The argument '{a} <round>' requires a value but none was supplied")
            val=args[i+1]
            rm=parse_duration_str(val)
            if rm is None:
                oprint(f'Can not parse "{val}" as duration. Argument for --round is ignored\n')
            else:
                round_minutes=rm
            i+=2
        elif a in ("-h","--help"):
            oprint(HELP_LIST)
            sys.exit(0)
        elif a.startswith("-"):
            error_sub_usage("list", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        else:
            error_sub_usage("list", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
