def handle_search(fp, args):
    if "-h" in args or "--help" in args:
        oprint(HELP_SEARCH)
        sys.exit(0)
    term=""
    if len(args)==0:
        term=""
    elif len(args)==1 and not args[0].startswith("-"):
        term=args[0]
    else:
        for a in args:
            if a.startswith("-"):
                error_sub_usage("search", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        if len(args)>1:
            error_sub_usage("search", f"error: Found argument '{args[1]}' which wasn't expected, or isn't valid in this context")
        term=args[0] if args else ""
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    for ln,line,typ in errs:
        oprint(f"Warning: Ignoring line {ln}. Please see `bartib check` for further information\n")
    if errs:
        oprint("\n")
    sorted_acts=sorted(acts, key=lambda a: a["start"])
    distinct=[]
    seen=set()
    for act in reversed(sorted_acts):
        key=(act["project"], act["description"])
        if key not in seen:
            seen.add(key)
            distinct.append(act)
    term_l=term.lower()
    filtered=[]
    for idx, act in enumerate(distinct):
        if term_l in act["project"].lower() or term_l in act["description"].lower():
            filtered.append((idx, act))
    if not filtered:
        oprint("No matching activities found\n\n")
        return
    filtered_sorted=sorted(filtered, key=lambda x: x[0], reverse=True)
    hdr_idx=" #"
    hdr_desc="Description"
    hdr_proj="Project"
    desc_vals=[act["description"] for _,act in filtered_sorted]
    proj_vals=[act["project"] for _,act in filtered_sorted]
    idx_strs=[f"[{idx}]" for idx,_ in filtered_sorted]
    w_idx=max(len(hdr_idx), max(len(s) for s in idx_strs) if idx_strs else 0)
    w_desc=max(len(hdr_desc), max(len(s) for s in desc_vals) if desc_vals else 0)
    w_proj=max(len(hdr_proj), max(len(s) for s in proj_vals) if proj_vals else 0)
    def pad(s,w): return s + NBSP*(w-len(s))
    oprint(f"\n\x1b[4m{pad(hdr_idx,w_idx)}\x1b[0m \x1b[4m{pad(hdr_desc,w_desc)}\x1b[0m \x1b[4m{pad(hdr_proj,w_proj)}\x1b[0m \n")
    for (idx,act), idx_s in zip(filtered_sorted, idx_strs):
        line=f"{pad(idx_s,w_idx)} {pad(act['description'],w_desc)} {pad(act['project'],w_proj)} \n"
        oprint(line)
    oprint("\n")

def handle_sanity(fp, args):
    if "-h" in args or "--help" in args:
