def handle_continue(fp, args):
    if "-h" in args or "--help" in args:
        oprint(HELP_CONTINUE)
        sys.exit(0)
    desc=None; proj=None; tstr=None
    positional=[]
    i=0
    while i<len(args):
        a=args[i]
        if a in ("-d","--description"):
            if i+1>=len(args):
                error_sub_usage("continue", f"error: The argument '{a} <DESCRIPTION>' requires a value but none was supplied")
            desc=args[i+1]; i+=2
        elif a in ("-p","--project"):
            if i+1>=len(args):
                error_sub_usage("continue", f"error: The argument '{a} <PROJECT>' requires a value but none was supplied")
            proj=args[i+1]; i+=2
        elif a in ("-t","--time"):
            if i+1>=len(args):
                error_sub_usage("continue", f"error: The argument '{a} <TIME>' requires a value but none was supplied")
            tstr=args[i+1]; i+=2
        elif a.startswith("-"):
            error_sub_usage("continue", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        else:
            positional.append(a); i+=1
    if len(positional)>1:
        error_sub_usage("continue", f"error: Found argument '{positional[1]}' which wasn't expected, or isn't valid in this context")
    number=0
    if positional:
        try:
            number=int(positional[0])
        except:
            oprint(f'Can not parse "{positional[0]}" as number. Argument for -n/--number is ignored\n')
            number=0
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    if not acts:
        eprint("Error: No activity has been started before.\n")
        sys.exit(0)
    sorted_acts=sorted(acts, key=lambda a: a["start"])
    distinct=[]
    seen=set()
    for act in reversed(sorted_acts):
        key=(act["project"], act["description"])
        if key not in seen:
            seen.add(key)
            distinct.append(act)
    if number<0 or number>=len(distinct):
        eprint(f"Error: Less than {number+1} distinct activities have been logged yet\n")
        sys.exit(1)
    target=distinct[number]
    new_proj=proj if proj is not None else target["project"]
    new_desc=desc if desc is not None else target["description"]
    now=get_now()
    new_start=now
    if tstr is not None:
        parsed,err=parse_time_arg(tstr)
        if parsed is None:
            if err=="out_of_range":
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input is out of range)\n')
            else:
                oprint(f'Can not parse "{tstr}" as time. Argument for -t/--time is ignored (input contains invalid characters)\n')
        else:
            new_start=parsed
    for act in acts:
        if act["end"] is None:
            diff=new_start-act["start"]
            mins=int(diff.total_seconds()//60)
            if mins<0: mins=0
            dur=format_duration(mins)
            oprint(f'Stopped activity: "{act["description"]}" ({act["project"]}) started at {format_datetime(act["start"])} ({dur})\n')
            act["end"]=new_start
    acts.append({"start":new_start,"end":None,"project":new_proj,"description":new_desc,"line_no":0,"raw":""})
    oprint(f'Started activity: "{new_desc}" ({new_proj}) at {format_datetime(new_start)}\n')
    write_file(fp, acts)

