    for ln, line, typ in errs:
        oprint(f"Warning: Ignoring line {ln}. Please see `bartib check` for further information\n")
    if errs:
        oprint("\n")
    running=[a for a in acts if a["end"] is None]
    if not running:
        oprint("No Activity is currently running\n")
        return
    hdr_started="Started At"
    hdr_desc="Description"
    hdr_proj="Project"
    hdr_dur="Duration"
    started_vals=[format_datetime(a["start"]) for a in running]
    desc_vals=[a["description"] for a in running]
    proj_vals=[a["project"] for a in running]
    now=get_now()
    dur_vals=[]
    for a in running:
        diff=now-a["start"]
        mins=int(diff.total_seconds()//60)
        if mins<0: mins=0
        dur_vals.append(format_duration(mins))
    w_started=max(len(hdr_started), max(len(s) for s in started_vals) if started_vals else 0)
    w_desc=max(len(hdr_desc), max(len(s) for s in desc_vals) if desc_vals else 0)
    w_proj=max(len(hdr_proj), max(len(s) for s in proj_vals) if proj_vals else 0)
    w_dur=max(len(hdr_dur), max(len(s) for s in dur_vals) if dur_vals else 0)
    def pad(s,w): return s + NBSP*(w-len(s))
    oprint(f"\n\x1b[4m{pad(hdr_started,w_started)}\x1b[0m \x1b[4m{pad(hdr_desc,w_desc)}\x1b[0m \x1b[4m{pad(hdr_proj,w_proj)}\x1b[0m \x1b[4m{pad(hdr_dur,w_dur)}\x1b[0m \n")
    for a, d in zip(running, dur_vals):
        line=f"{pad(format_datetime(a['start']),w_started)} {pad(a['description'],w_desc)} {pad(a['project'],w_proj)} {pad(d,w_dur)} \n"
        oprint(line)
    oprint("\n")

