        act_date=act["start"].date()
        if date_filter is not None:
            if act_date!=date_filter: continue
        else:
            if today and act_date!=today_date: continue
            if yesterday and act_date!=yesterday_date: continue
            if current_week and not (monday_current <= act_date <= sunday_current): continue
            if last_week and not (monday_last <= act_date <= sunday_last): continue
            if from_date is not None and act_date < from_date: continue
            if to_date is not None and act_date > to_date: continue
        filtered.append(act)
    filtered=sorted(filtered, key=lambda a: a["start"])
    if number is not None:
        if number < len(filtered):
            filtered=filtered[-number:]
    if not filtered:
        oprint("No activity to display\n\n")
        return
    now=get_now()
    disp=[]
    for act in filtered:
        start_dt=round_datetime(act["start"], round_minutes) if round_minutes else act["start"]
        if act["end"] is not None:
            end_dt=round_datetime(act["end"], round_minutes) if round_minutes else act["end"]
        else:
            end_dt=None
        if no_grouping:
            start_str=format_datetime(start_dt)
        else:
            start_str=format_time(start_dt)
        if end_dt is not None:
            stopped_str=format_time(end_dt)
        else:
            stopped_str="-"
        if end_dt is not None:
            diff=end_dt - start_dt
        else:
            now_r=round_datetime(now, round_minutes) if round_minutes else now
            diff=now_r - start_dt
        mins=int(diff.total_seconds()//60)
        if mins<0: mins=0
        dur=format_duration(mins)
        disp.append((act, start_str, stopped_str, dur, start_dt))
    hdr_started="Started"
    hdr_stopped="Stopped"
    hdr_desc="Description"
    hdr_proj="Project"
    hdr_dur="Duration"
    if no_grouping:
        w_started=max(len(hdr_started), max(len(s) for _,s,_,_,_ in disp))
        w_stopped=max(len(hdr_stopped), max(len(s) for _,_,s,_,_ in disp))
    else:
        w_started=max(len(hdr_started), max(len(s) for _,s,_,_,_ in disp))
        w_stopped=max(len(hdr_stopped), max(len(s) for _,_,s,_,_ in disp))
    max_desc=max(len(a["description"]) for a,_,_,_,_ in disp) if disp else 0
    max_proj=max(len(a["project"]) for a,_,_,_,_ in disp) if disp else 0
    max_dur=max(len(d) for _,_,_,d,_ in disp) if disp else 0
    w_desc=max(len(hdr_desc), max_desc)
    w_proj=max(len(hdr_proj), max_proj)
    w_dur=max(len(hdr_dur), max_dur)
    def pad(s,w): return s + NBSP*(w-len(s))
    if no_grouping:
        header=f"\n\x1b[4m{pad(hdr_started,w_started)}\x1b[0m \x1b[4m{pad(hdr_stopped,w_stopped)}\x1b[0m \x1b[4m{pad(hdr_desc,w_desc)}\x1b[0m \x1b[4m{pad(hdr_proj,w_proj)}\x1b[0m \x1b[4m{pad(hdr_dur,w_dur)}\x1b[0m \n"
        oprint(header)
        for act, s, e, d, _ in disp:
            is_running=act["end"] is None
            if is_running:
                line=f"\x1b[32m{pad(s,w_started)}\x1b[0m \x1b[32m{pad(e,w_stopped)}\x1b[0m \x1b[32m{pad(act['description'],w_desc)}\x1b[0m \x1b[32m{pad(act['project'],w_proj)}\x1b[0m \x1b[32m{pad(d,w_dur)}\x1b[0m \n"
            else:
                line=f"{pad(s,w_started)} {pad(e,w_stopped)} {pad(act['description'],w_desc)} {pad(act['project'],w_proj)} {pad(d,w_dur)} \n"
            oprint(line)
        oprint("\n")
    else:
        header=f"\n\x1b[4m{pad(hdr_started,w_started)}\x1b[0m \x1b[4m{pad(hdr_stopped,w_stopped)}\x1b[0m \x1b[4m{pad(hdr_desc,w_desc)}\x1b[0m \x1b[4m{pad(hdr_proj,w_proj)}\x1b[0m \x1b[4m{pad(hdr_dur,w_dur)}\x1b[0m \n\n"
        oprint(header)
        from collections import defaultdict
        groups=defaultdict(list)
        for item in disp:
            groups[item[4].date()].append(item)
        sorted_dates=sorted(groups.keys())
        for d in sorted_dates:
            items=groups[d]
            total_mins=0
            for act,s,e,_, start_dt in items:
                start_dt_r=round_datetime(act["start"], round_minutes) if round_minutes else act["start"]
                if act["end"] is not None:
                    end_dt_r=round_datetime(act["end"], round_minutes) if round_minutes else act["end"]
                    diff=end_dt_r - start_dt_r
                else:
                    now_r=round_datetime(now, round_minutes) if round_minutes else now
                    diff=now_r - start_dt_r
                mins=int(diff.total_seconds()//60)
                if mins<0: mins=0
                total_mins+=mins
            total_dur=format_duration(total_mins)
            oprint(f"\x1b[1m{d}\t{total_dur}\x1b[0m\n")
            for act,s,e, dur, _ in items:
                is_running=act["end"] is None
                if is_running:
                    line=f"\x1b[32m{pad(s,w_started)}\x1b[0m \x1b[32m{pad(e,w_stopped)}\x1b[0m \x1b[32m{pad(act['description'],w_desc)}\x1b[0m \x1b[32m{pad(act['project'],w_proj)}\x1b[0m \x1b[32m{pad(dur,w_dur)}\x1b[0m \n"
                else:
                    line=f"{pad(s,w_started)} {pad(e,w_stopped)} {pad(act['description'],w_desc)} {pad(act['project'],w_proj)} {pad(dur,w_dur)} \n"
                oprint(line)
            oprint("\n")

def handle_report(fp, args):
    date_filter=None; from_date=None; to_date=None
    today=False; yesterday=False; current_week=False; last_week=False
    project_filter=None; round_minutes=None
    i=0
    while i<len(args):
        a=args[i]
        if a=="--current_week":
            current_week=True; i+=1
        elif a=="--last_week":
            last_week=True; i+=1
        elif a=="--today":
            today=True; i+=1
        elif a=="--yesterday":
            yesterday=True; i+=1
        elif a in ("-d","--date"):
            if i+1>=len(args):
                error_sub_usage("report", f"error: The argument '{a} <DATE>' requires a value but none was supplied")
            val=args[i+1]
            d=parse_date_str(val)
            if d is None:
                oprint(f'Can not parse "{val}" as date. Argument for -d/--date is ignored (input contains invalid characters)\n')
            else:
                date_filter=d
            i+=2
        elif a=="--from":
            if i+1>=len(args):
                error_sub_usage("report", f"error: The argument '{a} <FROM_DATE>' requires a value but none was supplied")
            val=args[i+1]
            d=parse_date_str(val)
            if d is None:
                oprint(f'Can not parse "{val}" as date. Argument for --from is ignored (input contains invalid characters)\n')
            else:
                from_date=d
            i+=2
        elif a=="--to":
            if i+1>=len(args):
                error_sub_usage("report", f"error: The argument '{a} <TO_DATE>' requires a value but none was supplied")
            val=args[i+1]
            d=parse_date_str(val)
            if d is None:
                oprint(f'Can not parse "{val}" as date. Argument for --to is ignored (input contains invalid characters)\n')
            else:
                to_date=d
            i+=2
        elif a in ("-p","--project"):
            if i+1>=len(args):
                error_sub_usage("report", f"error: The argument '{a} <PROJECT>' requires a value but none was supplied")
            project_filter=args[i+1]; i+=2
        elif a=="--round":
            if i+1>=len(args):
                error_sub_usage("report", f"error: The argument '{a} <round>' requires a value but none was supplied")
            val=args[i+1]
            rm=parse_duration_str(val)
            if rm is None:
                oprint(f'Can not parse "{val}" as duration. Argument for --round is ignored\n')
            else:
                round_minutes=rm
            i+=2
        elif a in ("-h","--help"):
            oprint(HELP_REPORT)
            sys.exit(0)
        elif a.startswith("-"):
            error_sub_usage("report", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        else:
            error_sub_usage("report", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    for ln,line,typ in errs:
        oprint(f"Warning: Ignoring line {ln}. Please see `bartib check` for further information\n")
    if errs:
        oprint("\n")
    filtered=[]
    today_date=ddate.today()
    yesterday_date=today_date - timedelta(days=1)
    monday_current=today_date - timedelta(days=today_date.weekday())
    sunday_current=monday_current + timedelta(days=6)
    monday_last=monday_current - timedelta(days=7)
    sunday_last=monday_current - timedelta(days=1)
    for act in acts:
        if project_filter is not None and act["project"]!=project_filter:
            continue
        act_date=act["start"].date()
        if date_filter is not None:
            if act_date!=date_filter: continue
        else:
            if today and act_date!=today_date: continue
            if yesterday and act_date!=yesterday_date: continue
            if current_week and not (monday_current <= act_date <= sunday_current): continue
            if last_week and not (monday_last <= act_date <= sunday_last): continue
            if from_date is not None and act_date < from_date: continue
            if to_date is not None and act_date > to_date: continue
        filtered.append(act)
    now=get_now()
    proj_desc_minutes={}
    total_by_proj={}
    total_all=0
    for act in filtered:
        start_dt=round_datetime(act["start"], round_minutes) if round_minutes else act["start"]
        if act["end"] is not None:
            end_dt=round_datetime(act["end"], round_minutes) if round_minutes else act["end"]
            diff=end_dt - start_dt
        else:
            now_r=round_datetime(now, round_minutes) if round_minutes else now
            diff=now_r - start_dt
        mins=int(diff.total_seconds()//60)
        if mins<0: mins=0
        proj=act["project"]
        desc=act["description"]
        if proj not in proj_desc_minutes:
            proj_desc_minutes[proj]={}
            total_by_proj[proj]=0
        proj_desc_minutes[proj][desc]=proj_desc_minutes[proj].get(desc,0)+mins
        total_by_proj[proj]+=mins
        total_all+=mins
    max_width=0
    for proj in proj_desc_minutes:
        max_width=max(max_width, len(proj))
        for desc in proj_desc_minutes[proj]:
            max_width=max(max_width, len(desc)+4)
    max_width=max(max_width, len("Total"))
    def format_dotted(name, mins):
        dur=format_duration(mins)
        base=len(name)
        dots=max_width - base
        if dots<=0:
            return f"{name} {dur}"
        else:
            return f"{name}{'.'*dots} {dur}"
    sorted_projects=sorted(proj_desc_minutes.keys())
    for proj in sorted_projects:
        oprint(f"\x1b[1m{format_dotted(proj, total_by_proj[proj])}\x1b[0m\n")
        for desc in sorted(proj_desc_minutes[proj].keys()):
            mins=proj_desc_minutes[proj][desc]
            name="    "+desc
            oprint(f"{format_dotted(name, mins)}\n")
        oprint("\n")
    oprint(f"\x1b[1m{format_dotted('Total', total_all)}\x1b[0m\n\n")

