        sys.exit(0)
    if args:
        for a in args:
            if a.startswith("-"):
                error_sub_usage("sanity", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
            else:
                error_sub_usage("sanity", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    msgs=[]
    for act in acts:
        if act["end"] is not None and act["end"] < act["start"]:
            msgs.append(f"Activity has negative duration\n{act['description']} (Started: {format_datetime(act['start'])}, Ended: {format_datetime(act['end'])}, Line: {act['line_no']})\n\n")
    sorted_acts=sorted(acts, key=lambda a: a["start"])
    latest_end=None
    for act in sorted_acts:
        if latest_end is not None and act["start"] < latest_end:
            ended_str=format_datetime(act["end"]) if act["end"] else "--"
            msgs.append(f"Activity started before another activity ended\n{act['description']} (Started: {format_datetime(act['start'])}, Ended: {ended_str}, Line: {act['line_no']})\n\n")
        if act["end"] is not None:
            if latest_end is None or act["end"] > latest_end:
                latest_end=act["end"]
    if not msgs:
        oprint("No unusual activities.\n")
    else:
        for m in msgs:
            oprint(m)

