def handle_status(fp, args):
    if "-h" in args or "--help" in args:
        oprint(HELP_STATUS)
        sys.exit(0)
    project_filter=None
    i=0
    while i<len(args):
        a=args[i]
        if a in ("-p","--project"):
            if i+1>=len(args):
                error_sub_usage("status", f"error: The argument '{a} <PROJECT>' requires a value but none was supplied")
            project_filter=args[i+1]; i+=2
        elif a.startswith("-"):
            error_sub_usage("status", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        else:
            error_sub_usage("status", f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
    fp=ensure_file_arg(fp)
    acts,errs,err=read_file(fp)
    if err=="not_found":
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    No such file or directory (os error 2)\n")
        sys.exit(1)
    elif err:
        eprint(f"Error: Could not read from file: {fp}\n\nCaused by:\n    {err}\n")
        sys.exit(1)
    for ln,line,typ in errs:
        oprint(f"Warning: Ignoring line {ln}. Please see `bartib check` for further information\n")
    if errs:
        oprint("\n")
    if project_filter is not None:
        acts_filtered=[a for a in acts if a["project"]==project_filter]
    else:
        acts_filtered=acts
    running=[a for a in acts_filtered if a["end"] is None]
    today_date=ddate.today()
    monday_current=today_date - timedelta(days=today_date.weekday())
    sunday_current=monday_current + timedelta(days=6)
    first_month=ddate(today_date.year, today_date.month, 1)
    if today_date.month==12:
        next_month=ddate(today_date.year+1,1,1)
    else:
        next_month=ddate(today_date.year, today_date.month+1,1)
    last_month=next_month - timedelta(days=1)
    today_mins=0; week_mins=0; month_mins=0
    now=get_now()
    for act in acts_filtered:
        if act["end"] is not None:
            diff=act["end"] - act["start"]
        else:
            diff=now - act["start"]
        mins=int(diff.total_seconds()//60)
        if mins<0: mins=0
        ad=act["start"].date()
        if ad==today_date:
            today_mins+=mins
        if monday_current <= ad <= sunday_current:
            week_mins+=mins
        if first_month <= ad <= last_month:
            month_mins+=mins
    if project_filter is None:
        oprint(f"\x1b[2m\n =======\x1b[0m\x1b[3m Status for \x1b[0m\x1b[1mALL\x1b[0m\x1b[3m projects \x1b[0m\x1b[2m ======= \n\x1b[0m")
    else:
        oprint(f"\x1b[2m\n =======\x1b[0m\x1b[3m Status for project: \x1b[0m\x1b[1m{project_filter}\x1b[0m\x1b[2m ======= \n\x1b[0m")
    oprint("\x1b[2;3m\n  NOW: \x1b[0m")
    if running:
        cur=max(running, key=lambda a: a["start"])
        dur=format_duration(int((now - cur["start"]).total_seconds()//60) if (now - cur["start"]).total_seconds()>0 else 0)
        if project_filter is None:
            oprint(f"\x1b[1;32m{cur['description']}\x1b[0m\x1b[2;3m on \x1b[0m\x1b[3m{cur['project']}\x1b[0m\x1b[2m ...... \x1b[0m\x1b[1m{dur}\x1b[0m\x1b[2m\n\n\x1b[0m")
        else:
            oprint(f"\x1b[1;32m{cur['description']}\x1b[0m\x1b[2m ...... \x1b[0m\x1b[1m{dur}\x1b[0m\x1b[2m\n\n\x1b[0m")
    else:
        oprint("\x1b[1m NO Activity\n\x1b[0m\x1b[2m\n\n\x1b[0m")
    # Today etc
    oprint(f"\x1b[3m \x1b[0m\x1b[2;3m Today......................... \x1b[0m\x1b[1m{format_duration(today_mins)}\x1b[0m\x1b[3m\n\x1b[0m")
    oprint(f"\x1b[3m \x1b[0m\x1b[2;3m Current week.................. \x1b[0m\x1b[1m{format_duration(week_mins)}\x1b[0m\x1b[3m\n\x1b[0m")
    oprint(f"\x1b[3m \x1b[0m\x1b[2;3m Current month................. \x1b[0m\x1b[1m{format_duration(month_mins)}\x1b[0m\x1b[3m\n\x1b[0m\n")

def main():
    args=sys.argv[1:]
    # global help/version before parsing -f
    # Need to handle --help/-h and -V/--version globally even without subcommand
    # Also handle help subcommand
    # Parse global
    file_path=os.environ.get("BARTIB_FILE")
    # manual global parse to handle -f before subcommand and global flags
    # We'll reuse similar logic to earlier parse_global but now with corrected handling for missing subcommand
    i=0
    subcommand=None
    sub_args=[]
    # We'll iterate args to find subcommand position, handling -f
    # Need to support -f with value
    temp_args=args[:]
    # First, check for global help/version before any subcommand?
    # Actually global help/version can appear anywhere before subcommand? Let's handle during iteration
    idx=0
    # We'll loop
    while idx < len(args):
        a=args[idx]
        if a=="-f":
            if idx+1>=len(args):
                eprint("error: The argument '-f <FILE>' requires a value but none was supplied\n\nUSAGE:\n    executable [OPTIONS] <SUBCOMMAND>\n\nFor more information try --help\n")
                sys.exit(1)
            file_path=args[idx+1]
            idx+=2
            continue
        elif a in ("-h","--help"):
            # if we haven't seen subcommand yet, it's global help
            # need to decide: if subcommand already found, this would be subcommand help, but we handle global first only before subcommand
            # We'll treat as global help if subcommand is None
            if subcommand is None:
                oprint(GLOBAL_HELP)
                sys.exit(0)
            else:
                # let subcommand handle
                sub_args.append(a)
                idx+=1
                continue
        elif a in ("-V","--version"):
            if subcommand is None:
                oprint(f"bartib {VERSION}\n")
                sys.exit(0)
            else:
                sub_args.append(a)
                idx+=1
                continue
        elif a=="help":
            # help subcommand
            remaining=args[idx+1:]
            if not remaining:
                oprint(GLOBAL_HELP)
                sys.exit(0)
            else:
                for sub in remaining:
                    if sub in HELP_MAP:
                        oprint(HELP_MAP[sub])
                        sys.exit(0)
                    else:
                        eprint(f"error: The subcommand '{sub}' wasn't recognized\n\nUSAGE:\n\texecutable help <subcommands>...\n\nFor more information try --help\n")
                        sys.exit(1)
        elif a.startswith("-"):
            if subcommand is None:
                eprint(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [OPTIONS] <SUBCOMMAND>\n\nFor more information try --help\n")
                sys.exit(1)
            else:
                sub_args.append(a)
                idx+=1
                continue
        else:
            # subcommand
            if subcommand is None:
                subcommand=a
                sub_args=args[idx+1:]
                break
            else:
                sub_args.append(a)
                idx+=1
        idx+=1
    if subcommand is None:
        # No subcommand provided
        oprint(GLOBAL_HELP)
        sys.exit(1)
    # dispatch
    if subcommand=="start":
        handle_start(file_path, sub_args)
    elif subcommand=="stop":
        handle_stop(file_path, sub_args)
    elif subcommand=="cancel":
        handle_cancel(file_path, sub_args)
    elif subcommand=="change":
        handle_change(file_path, sub_args)
    elif subcommand=="continue":
        handle_continue(file_path, sub_args)
    elif subcommand=="current":
        handle_current(file_path, sub_args)
    elif subcommand=="edit":
        handle_edit(file_path, sub_args)
    elif subcommand=="last":
        handle_last(file_path, sub_args)
    elif subcommand=="list":
        handle_list(file_path, sub_args)
    elif subcommand=="report":
        handle_report(file_path, sub_args)
    elif subcommand=="projects":
        handle_projects(file_path, sub_args)
    elif subcommand=="search":
        handle_search(file_path, sub_args)
    elif subcommand=="sanity":
        handle_sanity(file_path, sub_args)
    elif subcommand=="check":
        handle_check(file_path, sub_args)
    elif subcommand=="status":
        handle_status(file_path, sub_args)
    elif subcommand=="help":
        # shouldn't reach here because handled above, but handle "help" without args already
        oprint(GLOBAL_HELP)
        sys.exit(0)
    else:
        eprint(f"error: Found argument '{subcommand}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [OPTIONS] <SUBCOMMAND>\n\nFor more information try --help\n")
        sys.exit(1)

if __name__=="__main__":
    main()
